def solve_for_n(n):
    N = 2 * n + 1

    # Dictionary to store frequencies of each index i (0 to N-1)
    frequencies = {i: 0 for i in range(N)}

    # Calculate F_k = k(k+1)/2 mod N for k = 1 to N
    for k in range(1, N + 1):
        # Calculate T_k = k(k+1)/2
        T_k = k * (k + 1) // 2

        # Calculate the residue i_k = T_k mod N
        i_k = T_k % N

        # Increment frequency
        frequencies[i_k] += 1

    # Count the number of indices i where the frequency m_i is odd
    odd_frequency_count = 0
    for i in range(N):
        if frequencies[i] % 2 != 0:
            odd_frequency_count += 1

    return N, frequencies, odd_frequency_count

results = {}
for n in [1, 2, 3, 4]:
    N, freqs, count = solve_for_n(n)
    results[n] = {
        "N": N,
        "frequencies": freqs,
        "heads_down_count": count
    }

# Print results in a readable format
print("--- Results ---")
for n, data in results.items():
    print(f"\nn = {n}, N = {data['N']}")
    print(f"Frequencies (m_i): {data['frequencies']}")
    print(f"Total number of coins facing heads down: {data['heads_down_count']}")

