def solve_large(n):
    num_coins = 2 * n + 1
    flips = []
    for k in range(1, 2 * n + 2):
        flips.append((k * (k + 1) // 2 - 1) % num_coins)

    count = [0] * num_coins
    for f in flips:
        count[f] += 1

    tails = sum(1 for c in count if c % 2 == 1)
    return tails

for n in [100, 1000, 10000]:
    print(f"n={n}, tails={solve_large(n)}")

